package main

import (
	"bytes"
	"crypto/hkdf"
	"crypto/mlkem"
	"crypto/sha256"
	"fmt"
)

func main() {
	// Receiver: make a key pair. Publish ek; store the 64-byte seed like a private key.
	dk, err := mlkem.GenerateKey768()
	if err != nil {
		panic(err)
	}
	ek := dk.EncapsulationKey().Bytes()
	fmt.Println("encapsulation key:", len(ek), "bytes; private seed:", len(dk.Bytes()), "bytes")

	// Sender: parsing ek runs the FIPS 203 input check, then encapsulate.
	pub, err := mlkem.NewEncapsulationKey768(ek)
	if err != nil {
		panic(err)
	}
	ssSender, ct := pub.Encapsulate()
	fmt.Println("ciphertext:", len(ct), "bytes; shared secret:", len(ssSender), "bytes")

	// Receiver: decapsulate the ciphertext it was sent.
	ssReceiver, err := dk.Decapsulate(ct)
	fmt.Println("secrets match:", bytes.Equal(ssSender, ssReceiver), "err:", err)

	// Derive purpose-bound keys from the secret instead of using it raw everywhere.
	key, _ := hkdf.Key(sha256.New, ssReceiver, nil, "files v1 aes-256-gcm", 32)
	fmt.Println("derived AES-256 key:", len(key), "bytes")
}

// Output:
// encapsulation key: 1184 bytes; private seed: 64 bytes
// ciphertext: 1088 bytes; shared secret: 32 bytes
// secrets match: true err: <nil>
// derived AES-256 key: 32 bytes

package main

import (
	"bytes"
	"crypto/mlkem"
	"fmt"
)

func main() {
	dk, _ := mlkem.GenerateKey768()
	ek := dk.EncapsulationKey().Bytes()
	ss, ct := dk.EncapsulationKey().Encapsulate()

	// 1. A ciphertext changed in transit: Decapsulate does NOT return an
	//    error (implicit rejection). It returns an unrelated secret, so the
	//    AEAD tag check on the first message is what fails.
	bad := bytes.Clone(ct)
	bad[0] ^= 0x01
	ss2, err := dk.Decapsulate(bad)
	fmt.Println("tampered ct: err =", err, "| same secret =", bytes.Equal(ss, ss2))

	// 2. Wrong length is rejected outright.
	_, err = dk.Decapsulate(ct[:1000])
	fmt.Println("short ct:   ", err)

	// 3. An encapsulation key holding a coefficient >= q (3329) fails the
	//    FIPS 203 modulus check when it is parsed.
	odd := bytes.Clone(ek)
	odd[0], odd[1] = 0xFF, odd[1]|0x0F // first 12-bit coefficient = 4095
	_, err = mlkem.NewEncapsulationKey768(odd)
	fmt.Println("bad ek:     ", err)
}

// Output:
// tampered ct: err = <nil> | same secret = false
// short ct:    mlkem: invalid ciphertext length
// bad ek:      mlkem: invalid polynomial encoding

