package main

import (
	"bytes"
	"crypto/ecdh"
	"crypto/mlkem"
	"crypto/rand"
	"crypto/sha3"
	"fmt"
)

// SP 800-227 style combiner: hash BOTH secrets AND both ciphertexts and keys,
// plus a label naming this exact construction. All inputs are fixed-length.
func combine(k1, k2, c1, c2, ek1, ek2 []byte) []byte {
	h := sha3.New256()
	for _, part := range [][]byte{k1, k2, c1, c2, ek1, ek2} {
		h.Write(part)
	}
	h.Write([]byte("example-app hybrid MLKEM768+X25519 v1"))
	return h.Sum(nil)
}

func main() {
	// Receiver publishes two keys.
	dkPQ, _ := mlkem.GenerateKey768()
	skEC, _ := ecdh.X25519().GenerateKey(rand.Reader)
	ekPQ, ekEC := dkPQ.EncapsulationKey().Bytes(), skEC.PublicKey().Bytes()

	// Sender: one ML-KEM encapsulation plus one ephemeral X25519.
	pq, _ := mlkem.NewEncapsulationKey768(ekPQ)
	k1, c1 := pq.Encapsulate()
	eph, _ := ecdh.X25519().GenerateKey(rand.Reader)
	k2, _ := eph.ECDH(skEC.PublicKey())
	c2 := eph.PublicKey().Bytes()
	sender := combine(k1, k2, c1, c2, ekPQ, ekEC)

	// Receiver recomputes both halves.
	r1, _ := dkPQ.Decapsulate(c1)
	peer, _ := ecdh.X25519().NewPublicKey(c2)
	r2, _ := skEC.ECDH(peer)
	receiver := combine(r1, r2, c1, c2, ekPQ, ekEC)

	fmt.Println("sent:", len(c1)+len(c2), "bytes; keys match:", bytes.Equal(sender, receiver))
}

// Output:
// sent: 1120 bytes; keys match: true

package main

import (
	"crypto/ecdh"
	"crypto/mlkem"
	"crypto/rand"
	"fmt"
)

// Callers name an algorithm ID; only this file knows the libraries.
type KEM func(peerKey []byte) (secret, ct []byte, err error)

func mlkem768(pk []byte) ([]byte, []byte, error) {
	ek, err := mlkem.NewEncapsulationKey768(pk) // runs the FIPS 203 check
	if err != nil {
		return nil, nil, err
	}
	ss, ct := ek.Encapsulate()
	return ss, ct, nil
}

func x25519(pk []byte) ([]byte, []byte, error) {
	peer, err := ecdh.X25519().NewPublicKey(pk)
	if err != nil {
		return nil, nil, err
	}
	eph, _ := ecdh.X25519().GenerateKey(rand.Reader)
	ss, err := eph.ECDH(peer)
	return ss, eph.PublicKey().Bytes(), err
}

var registry = map[string]KEM{"mlkem768": mlkem768, "x25519": x25519}

// Policy is data: loaded from config, so retiring an algorithm needs no code change.
var allowedForNewData = map[string]bool{"mlkem768": true, "x25519": false}

func Encap(alg string, pk []byte) ([]byte, []byte, error) {
	kem, ok := registry[alg]
	if !ok || !allowedForNewData[alg] {
		return nil, nil, fmt.Errorf("algorithm %q not allowed by policy", alg)
	}
	return kem(pk)
}

func main() {
	dk, _ := mlkem.GenerateKey768()
	_, ct, err := Encap("mlkem768", dk.EncapsulationKey().Bytes())
	fmt.Println("mlkem768:", len(ct), "byte ciphertext, err:", err)

	xk, _ := ecdh.X25519().GenerateKey(rand.Reader)
	_, _, err = Encap("x25519", xk.PublicKey().Bytes())
	fmt.Println("x25519:  ", err)
}

// Output:
// mlkem768: 1088 byte ciphertext, err: <nil>
// x25519:   algorithm "x25519" not allowed by policy
